return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Biçe Lêgerîna Pêvekê','Activate %s' => '%s çalak bike','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> hewce dike ku <strong>%2$s</strong> were sazkirin û aktîfkirin. <a href="%4$s">%3$s</a>','Enter your code here' => 'Koda xwe li vir binivîse','Add %s' => '%s zêde bike','Remove' => 'Dûrxistin','Order number and receipt will be sent to this email address.' => 'Hejmara fermanê û meqbûz dê ji vê navnîşana e-nameyê re were şandin.','Apartment, unit, building, floor, etc.' => 'Apartman, yekîne, avahî, qat, hwd.','Shipping phone' => 'Telefona barkirinê','Only used for shipping-related questions.' => 'Tenê ji bo pirsên barkêş-girêdayî tê bikar anîn.','Single step' => 'Yek gav','Click to go to the order summary' => 'Bikirtînin da ku biçin ser kurteya fermanê','Cart total:' => 'Tevahiya selikê:','Proceed to %s' => 'Biçe %s','Proceed to contact' => 'Bikevin têkiliyê','Proceed to shipping' => 'Ber bi sewqiyata biçe','Proceed to billing' => 'Ber bi fatûreyê ve biçin','Proceed to payment' => 'Berdewam bike ji bo dayina','Shipping method' => 'Rêbaza barkirinê','Additional notes' => 'Têbînî Additional','Payment method' => 'Rêbaza dayinê','Step %1$s of %2$s' => 'Gav %1$s ji %2$s','Change: %s' => 'Guhertin: %s','Not selected yet.' => 'Hîn nehatiye hilbijartin.','Same as shipping address' => 'Eynî wekî navnîşana barkirinê','Same as billing address' => 'Eynî navnîşana billing','Order summary' => 'Kurte ferman','Edit cart' => 'Biguherîne selikê','Did you mean %s?' => 'Mebesta te %s bû?','Change email address to: {suggestion-value}' => 'Navnîşana e-nameyê biguherîne: {suggestion-value}','This is a required field.' => 'Ev qada pêwîst e.','This is not a valid email address.' => 'Ev ne navnîşana e-nameyek derbasdar e.','This field does not match the related field value.' => 'Ev qad bi nirxa zeviya têkildar re nagire.','The CPF number "{cpf_number}" is invalid.' => 'Hejmara CPF &quot;{cpf_number}&quot; nederbasdar e.','The CNPJ number "{cnpj_number}" is invalid.' => 'Hejmara CNPJ &quot;{cnpj_number}&quot; nederbasdar e.','(Required)' => '(Pêdivî ye)','Checkout Header - Desktop' => 'Sernivîsa Checkout - Sermaseya','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Ji bo ekranên mezin, widgetan li ser serê danûstendinê nîşan bidin. Tenê heke sernavê danûstendina pêvekê bikar bînin tê xuyang kirin.','Checkout Header - Mobile' => 'Sernivîsa Checkout - Mobile','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Ji bo cîhazên mobîl, widgetan li jêr sernavê danûstendinê nîşan bidin. Tenê heke sernavê danûstendina pêvekê bikar bînin tê xuyang kirin.','Checkout Sidebar' => 'Bara kêlekê ya kontrolê','Display widgets on the checkout sidebar after the order summary.' => 'Piştî kurteya fermanê widgetan li ser milê danûstendinê nîşan bidin.','Checkout Order Summary' => 'Kurteya Order Checkout','Display widgets inside the order summary at the checkout page.' => 'Di rûpela danûstendinê de widgetan di hundurê kurteya fermanê de nîşan bidin.','Checkout Below Place Order' => 'Checkout Li jêr Cihê Order','Display widgets below the place order button at the checkout page.' => 'Di rûpela danûstendinê de widgetan li binê bişkoja fermana cîh nîşan bidin.','Checkout Footer' => 'Checkout Footer','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Widgetan li ser pêlava danûstendinê nîşan bidin. Tenê heke pênûsa danûstendinê ya pêvekê bikar bîne tê xuyang kirin.','Classic' => 'Classic','Boxed' => 'Boxed','Split' => 'Qelişandin','Minimalist' => 'Minimalist','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Pêvekên Fluid Checkout û Dîroka Radestkirinê ji hêla CodeRockz ve','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Me tesbît kir ku hûn pêvekên Demjimêra Demjimêra Radestkirin &amp; Hilbijartinê ji bo WooCommerce (belaş û PRO) ji hêla CodeRockz ve bikar tînin. Yekbûna bi van pêvekan re li Fluid Checkout PRO hate veguheztin.</p>','Upgrade to PRO' => 'Nûvekirina PRO','Fluid Checkout database updated successfully' => 'Databasa Fluid Checkout bi serkeftî hate nûve kirin','The database changes where applied successfully.' => 'Li cîhê ku bi serfirazî tête bikar anîn databas diguhere.','Dismiss' => 'Berdan','Fluid Checkout database update' => 'Nûvekirina databasa Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Hin guhertinên databasê hewce ne. Mîna her nûvekirinê, em ji we re pêşniyar dikin ku <strong>berî ku hûn bidomînin ji malpera xwe kopiyek tam bistînin</strong> .','Update database' => 'Databasê nûve bikin','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout bi sêwirana danûstendinê ya Divi Builder re ne hevaheng e','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Pêdivî ye ku Fluid Checkout forma danûstendinê ya li ser bingeha kurteya WooCommerce ya klasîk bixebite. Dema ku Divi Builder bikar tînin da ku xuyang û hesta rûpela danûstendinê xweş bikin, kurtekodên klasîk ji bo her beşê rûpela danûstendinê bi widgetên xwerû yên ji Divi Builder têne guheztin. Van widgetên xwerû bi Fluid Checkout re ne hevaheng in.</p><p> Ji kerema xwe rûpela xweya danûstendinê biguherîne û li şûna widgetên Divi Builder widgetek nivîsê ya ku koda kurt <code>[woocommerce_checkout]</code> heye biguherîne.</p>','Edit the checkout page' => 'Rûpelê danûstendinê biguherînin','Read the documentation.' => 'Belgenameyê bixwînin.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Dema ku Fluid Checkout bikar tîne pêdivî ye ku taybetmendiya danûstendina pir-gavekî ya PRO ya almankirî were neçalak kirin','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Dema ku Fluid Checkout bikar tîne, taybetmendiya pir gavê ji pêveka PRO ya Germanized nepêwist dibe û dibe sedema <strong>xeletiyên krîtîk dema ku fermanên nû hilîne</strong> . Ji kerema xwe di mîhengên pêvekê de taybetmendiya danûstendina pir gavê ya PRO ya Germanized neçalak bike.','Go to Germanized settings' => 'Herin mîhengên elmanîkirî','Thanks for choosing Fluid Checkout!' => 'Spas ji bo hilbijartina Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Hûn ji bo demekê pêvekê bikar tînin. Heta niha tu çawa jê hez dikî?<br> Ji kerema xwe nirxek bilez ji me re bidin, em ji her bitek berteka xwe teqdîr dikin û ew me teşwîq dike ku em pêvekê bidomînin :)','Rate the plugin' => 'Pêvekê binirxînin','I need help!' => 'Ez alîkarî divê!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Hin taybetmendiyên WooCommerce Checkout Manager ji hêla Quadlayers ve dibe ku dema ku ew bi Fluid Checkout re bikar tînin wekî ku tê hêvî kirin nexebitin. Ji bo bêtir agahdarî û çareseriyên alternatîf <a href="%s">belgeyên me</a> bixwînin.','Read documentation' => 'Belgekirin bixwînin','Don\'t show this again' => 'Vê carek din nîşan nedin','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Zêdetir şablonên sêwiranê','Optimized cart page' => 'rûpel cart Optimized','Optimized order received / thank you page' => 'Fermana xweşbînkirî hatî wergirtin / rûpela spas','Edit cart contents at checkout page' => 'Di rûpela danûstendinê de naveroka selikê biguherînin','Account matching / user matching' => 'Lihevhatina hesabê / berhevdana bikarhêner','Trust symbols on the cart and thank you pages' => 'Sembolên pêbaweriyê li ser rûpelên selikê û spas','More positions for the coupon code on the checkout page' => 'Ji bo koda kuponê li ser rûpela danûstendinê bêtir pozîsyon','International phone numbers' => 'Hejmarên têlefonên navneteweyî','Gift messages and packing slips' => 'Peyamên diyariyê û pelikên pakkirinê','Local pickup and in-store collection' => 'Hilbijartina herêmî û berhevoka nav-firoşgehê','EU-VAT Assistant' => 'Alîkarê YE-VAT','I already have it – Hide this offer' => 'Min jixwe ew heye - Vê pêşniyarê veşêre','Activated' => 'Activated','Address book' => 'Pirtûka navnîşan','Select an image' => 'Wêneyek hilbijêre','Cart layout' => 'layout selikê','Cart optimizations' => 'Optimîzasyonên selikê','Enable cart page optimizations' => 'Optimîzasyonên rûpela selikê çalak bikin','Header and footer template' => 'Şablona sernivîs û pêlavê','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Kontrol dike ka meriv sernav û pêpelûka rûpela belaş a balkêş bikar bîne an sernav û pêveka mijara heyî ya çalak bihêle.','Distraction free header and footer' => 'Sernivîs û pêlava bê baldarî','Theme\'s header and footer' => 'Sernivîs û pêlava mijarê','Cart elements' => 'hêmanên selikê','Make the order summary stay visible on the cart page while scrolling' => 'Kurteya fermanê dema ku digere li ser rûpela selikê xuya bibe','Coupon codes' => 'Kodên kuponê','Hidden' => 'Veşartî','Before the cart items section' => 'Berî beşa tiştên selikê','Inside the cart items section' => 'Di hundurê beşa tiştên selikê de','After the cart items section' => 'Piştî beşa tiştên selikê','Before the shipping section' => 'Berî beşa barkirinê','After the shipping section' => 'Piştî beşa barkirinê','Before the order summary' => 'Berî kurteya fermanê','Inside the order summary' => 'Di hundurê kurteya fermanê de','Before the order totals' => 'Berî ku emrê tevde bibe','After the order totals' => 'Piştî ku ferman bi tevahî','After the order summary' => 'Piştî kurteya fermanê','Shipping' => 'Shipping','Select position where to display the shipping costs and calculator on the cart page.' => 'Cihê ku lêçûnên barkirinê û hesabkerê li ser rûpela selikê nîşan bide hilbijêrin.','Display as a cart section' => 'Wek beşa selikê nîşan bide','Cross-sells' => 'Xecê difiroşe','Select position where to display the cross-sells section on the cart page.' => 'Cihê ku hûn li ser rûpela selikê beşa xaç-firotinê nîşan bidin hilbijêrin.','Before the cart actions' => 'Berî çalakiyên selikê','After the cart actions' => 'Piştî çalakiyên cart','Layout of cross-sell items on the cart page.' => 'Layout ji tiştên xaç-firotina li ser rûpel cart.','Optimized horizontal cross-sells layout' => 'Plansaziya xaç-firotina horizontî ya xweşbînkirî','Theme\'s cross-sells layout' => 'Plansaziya mijarê ya xaçê difroşe','Number of cross-sell items to display on the cart page' => 'Hejmara hêmanên xaçefiroş ên ku li ser rûpela selikê têne xuyang kirin','Add widget areas to the cart page' => 'Herêmên widgetê li rûpela selikê zêde bikin','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Van deverên widgetan têne bikar anîn ku li ser rûpelê selikê sembolên pêbaweriyê û nîşaneyên pêbaweriyê zêde bikin.','Checkout' => 'Lêkolîn','Checkout layout' => 'layout Checkout','Design template' => 'şablonê sêwiranê','Dark mode' => 'Moda tarî','Enable dark mode' => 'Moda tarî çalak bike','Logo image' => 'Wêne logo','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Wêneyek hilbijêrin ku li ser serê rûpela danûstendinê were xuyang kirin. Tenê dema ku sernav û pêpelûka belaş a baldarî bikar tînin tê sepandin.','Header background color' => 'Rengê paşperdeya sernavê','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Ji bo sernavê rûpela danûstendinê rengê paşxanê hilbijêrin. Tenê dema ku sernav û pêpelûka belaş a baldarî bikar tînin tê sepandin.','HTML color value. ie: #f3f3f3' => 'Nirxa rengê HTML. ango: #f3f3f3','Page background color' => 'Rengê paşxaneya rûpelê','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Ji bo rûpela danûstendinê rengek paşîn hilbijêrin. Reng li hêmana <em>laş</em> tê sepandin.','Footer background color' => 'Rengê paşperdeya jêrîn','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Ji bo pêpelûka rûpela danûstendinê rengek paşîn hilbijêrin. Tenê dema ku sernav û pêpelûka belaş a baldarî bikar tînin tê sepandin.','Progress bar' => 'Barê pêşveçûnê','Display the checkout progress bar when using multi-step checkout layout' => 'Dema ku nexşeya danûstendinê ya pir-gavekî bikar tînin, barê pêşkeftina danûstendinê nîşan bidin','Make the checkout progress bar stay visible while scrolling' => 'Bikin ku bara pêşkeftina danûstendinê di dema gerandinê de xuya bibe','Express checkout' => 'Checkout Express','Enable the express checkout section' => 'Beşa danûstendina bilez çalak bike','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Dema ku dergehên dravdanê yên piştgirîkirî ev taybetmendî çalak be di dema dravdanê de beşa danûstendina bilez nîşan dide.','Display express checkout buttons in one line for larger screens' => 'Ji bo ekranên mezin bişkokên danûstendina bilez di yek rêzê de nîşan bidin','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Dema ku bi dergehek dravdana dravdana bilez a lihevhatî re drav didin qadên pêwîst ên dravdanê yên zêde guh nedin','Make the order summary stay visible while scrolling' => 'Kurteya fermanê di dema gerandinê de xuya bibe','Choose a background color for the order summary section.' => 'Ji bo beşa kurteya fermanê rengek paşîn hilbijêrin.','Highlight the order totals row in the order summary table' => 'Di tabloya kurteya fermanê de rêza giştî ya fermanê ronî bike','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Dema ku beşa kurteya fermanê rengê paşxanê yê ronîkirî nebe, pir bikêrhatî ye. Dema ku Fluid Checkout PRO bikar bînin dibe ku li ser rûpelên Selik, Siparîşa Wergirtin û Dîtina Siparîşê jî were sepandin.','Action link on the order summary at checkout.' => 'Zencîreya çalakiyê ya li ser kurteya fermanê ya li dravdanê.','Edit cart link' => 'Girêdana selikê biguherîne','Cart items count' => 'Tiştên selikê têne hejmartin','Link to shop page' => 'Girêdana rûpela dikanê','Cart items' => 'Tiştên selikê','Hide cart items errors at the checkout page' => 'Di rûpela danûstendinê de xeletiyên tiştên selikê veşêrin','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Peyama çewtiyên selikê li serê rûpela danûstendinê nîşan nedin. Dema şandina forma dravdanê ji bo temamkirina kirînê, ev peyamên xeletiyê dê her gav bêne xuyang kirin.','Place order' => 'Cihê fermanê','Define the position to display "Place order" and terms checkbox section.' => 'Helwesta nîşankirina &quot;Serpirsiyarê&quot; û beşa kontrolê ya şertan diyar bikin.','Some options might not be compatible with some plugins and themes.' => 'Dibe ku hin vebijark bi hin pêvek û mijaran re hevaheng nebin.','Below the payment section' => 'Li jêr beşa dravdanê','Below the order summary' => 'Li jêr kurteya fermanê','Both below the payment section and the order summary' => 'Hem li jêr beşa dravdanê û hem jî kurteya fermanê','Add widget areas to the checkout page' => 'Herêmên widgetê li rûpela danûstendinê zêde bikin','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Van deverên widgetê têne bikar anîn ku li ser rûpela danûstendinê sembolên pêbaweriyê û nîşaneyên pêbaweriyê zêde bikin.','Display the coupon codes section title' => 'Sernavê beşa kodên kuponê nîşan bidin','Select position where to display the coupon codes section on the checkout page.' => 'Cihê ku hûn beşa kodên kuponê li ser rûpela danûstendinê nîşan bidin hilbijêrin.','Before the checkout steps' => 'Berî gavên danûstendinê','As a substep before payment methods' => 'Wekî binegavê berî awayên dravdanê','As a substep after payment methods' => 'Wekî binegavê piştî rêbazên dravdanê','Default button style' => 'Şêweya bişkojka xwerû','"Add" link button' => 'Bişkoka girêdanê &quot;lê zêde bike&quot;.','Checkout fields' => 'Zeviyên kontrolê','Optional fields' => 'zeviyên Bijarî','Hide optional fields behind a link button' => 'Zeviyên vebijarkî li pişt bişkojek girêdanê veşêrin','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Tête pêşniyar kirin ku vê vebijarkê were kontrol kirin da ku hejmara zeviyên têketina vekirî kêm bikin, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">lêkolînê bixwînin</a> .','Do not hide "Address line 2" fields behind a link button' => 'Zeviyên &quot;Rêza Navnîşan 2&quot; li pişt bişkojka girêdanê veneşêrin','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Tenê gava ku pir xerîdar bi rastî hewceyê qada &quot;Xeta Navnîşan 2&quot; hewce ne, an dema ku girtina navnîşana barkirinê ya rast girîng e (ango heke xwarin û hilberên din ên xerabûyî radest bikin) tê pêşniyar kirin.','Billing address' => 'Telefona berîkan','Select position where to display the billing address section on the checkout page.' => 'Cihê ku hûn beşa navnîşana fatûreyê li ser rûpela danûstendinê nîşan bidin hilbijêrin.','As a step before shipping' => 'Wekî gavek berî barkirinê','As a sub-step before the shipping address section' => 'Wekî bine-gaveke berî beşa navnîşana barkirinê','As a sub-step after the shipping address section' => 'Wekî jêr-gavek piştî beşa navnîşana barkirinê','As a step after shipping' => 'Wekî gavek piştî barkirinê','As a sub-step before the payment section' => 'Wekî bine-gaveke berî beşa dravdanê','Force billing and shipping addresses to the same (single section)' => 'Navnîşanên fatûre û barkirinê bi heman rengî (beşek yekane)','Checkbox for "Same as shipping/billing address" checked by default' => 'Qutiya kontrolê ya ji bo &quot;Eyn wekî navnîşana barkirinê/billing&quot; ji hêla xwerû ve hatî kontrol kirin','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Dema ku beşa navnîşana barkirinê pêşî were xuyang kirin qutîka kontrolê &quot;Eyn wekî navnîşana barkirinê&quot; dê ji hêla xwerû ve hatî kontrol kirin dest pê bike.<br> Dema ku beşa navnîşana fatûreyê yekem were xuyang kirin qutîka kontrolê &quot;Eyn wekî navnîşana fatûreyê&quot; dê ji hêla xwerû ve hatî kontrol kirin dest pê bike.<br> Tête pêşniyar kirin ku vê vebijarkê were kontrol kirin ji ber ku di dravdanê de hejmara zeviyên têketina vekirî bi girîngî kêm bikin, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">lêkolînê bixwînin</a> .','Highlight the billing address section in the checkout form' => 'Di forma danûstendinê de beşa navnîşana fatûreyê ronî bikin','Shipping address' => 'Navnîşana şandinê','Highlight the shipping address section in the checkout form' => 'Di forma danûstendinê de beşa navnîşana barkirinê ronî bikin','Shipping methods' => 'Rêbazên barkirinê','Choose in which position to display the shipping methods section.' => 'Hilbijêre ku li kîjan pozîsyonê beşa rêbazên barkirinê nîşan bide.','Before shipping address' => 'Berî navnîşana barkirinê','After shipping address' => 'Piştî navnîşana barkirinê','Local pickup' => 'Pişka herêmî','Removes shipping address section when a local pickup shipping method is selected.' => 'Dema ku rêbazek barkirinê ya herêmî tê hilbijartin, beşa navnîşana barkirinê radike.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Dema ku rêbazek barkirinê ya herêmî tê hilbijartin, navnîşana barkirinê bi cîhê xala hilgirtinê diguhezîne.','Choose which address to save as the shipping address for local pickup orders.' => 'Hilbijêre ku kîjan navnîşan wekî navnîşana barkirinê ji bo fermanên hilgirtina herêmî tomar bike.','Save the selected pickup location' => 'Cihê hilbijartî hilbijartî hilînin','Save same as the billing address' => 'Heman navnîşana fatûreyê hilînin','Do not save any shipping address' => 'Navnîşana barkirinê tomar nekin','Company name field for shipping address' => 'Qada navê pargîdaniyê ji bo navnîşana barkirinê','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Ji bo beşa navnîşana barkirinê ya li ser forma danûstendinê, dîtina qada navê pargîdaniyê biguhezînin.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Ger zevî wekî &quot;vebijarkî&quot; were danîn, ku ew rewşa dîtbarî ya xwerû ye, dê ti guhertin neyê sepandin da ku pêvekên din guheztinên ku hewce dikin bicîh bînin.','Hidden (remove field)' => 'Veşartî (qada rakirin)','Optional' => 'Bixwe','Required' => 'Required','Add shipping phone field to the checkout form.' => 'Qada têlefonê barkirinê li forma danûstendinê zêde bikin.','Choose in which step to display the shipping phone field.' => 'Hilbijêre ku di kîjan gavê de qada têlefonê barkirinê nîşan bide.','Contact step' => 'Pêngava têkiliyê','Billing phone' => 'Billing phone','Add billing phone field to the checkout form.' => 'Qada telefona fatûreyê li forma danûstendinê zêde bikin.','Choose in which step to display the billing phone field.' => 'Hilbijêre ku di kîjan gavê de qada têlefonê fatûreyê nîşan bide.','Show country code beside the flag' => 'Koda welat li kêleka alê nîşan bide','Show an example of a valid phone number inside phone fields' => 'Mînakek jimareyek têlefonê ya derbasdar di hundurê qadên têlefonê de nîşan bide','Do not change placeholders' => 'Cihên cihan neguherînin','Show if not defined' => 'Heke ne diyarkirî nîşan bide','Always show' => 'Her tim nîşan bide','Order notes' => 'Order notes','Define the visibility of the additional order notes field.' => 'Dîtina qada nîşeyên fermanê yên zêde diyar bikin.','Gift options' => 'Vebijarkên diyariyê','Allow customers to add a gift message and other gift related options to the order.' => 'Destûrê bidin xerîdar ku peyamek diyariyê û vebijarkên din ên têkildarî diyariyê li fermanê zêde bikin.','Display the gift message as part of the order details table instead of a separate section' => 'Li şûna beşek cûda, peyama diyariyê wekî beşek ji tabloya hûrguliyên fermanê nîşan bidin','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Vê vebijarkê bandorê li rûpela pejirandina fermanê (rûpela spas) dike û hûrguliyên fermanê li ser rûpelên hesab, e-name û pelikên pakkirinê dike.','Account matching' => 'Lihevhatina hesabê','Enable the account matching feature' => 'Taybetmendiya hevberdana hesabê çalak bike','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Dema ku hesabek jixwe bi hûrguliyên pêwendiya xerîdar re hebe, fermanên xerîdarên mêvan bi hesabê wan ên heyî re têkildar bikin.','Display message when an account exists with the email address provided' => 'Dema ku hesabek bi navnîşana e-nameyê hatî peyda kirin peyamek nîşan bide','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Zeviyên çêkirina hesaban bi agahiyek û vebijarkek têketinê diguhezîne. Di hin rewşan de, dibe ku were pêşniyar kirin ku hûn vê vebijarkê neçalak bihêlin da ku nepeniya xerîdar biparêzin.','Dashboard' => 'Dashboard','Integrations' => 'Integrations','License keys' => 'keys License de','Visit our website for more information about our plugins and add-ons.' => 'Ji bo bêtir agahdarî li ser pêvek û pêvekên me biçin malpera me.','Order pay page' => 'Siparîş bike rûpel pay','Order pay' => 'Siparîşa dayina','Enable order pay page optimizations' => 'Optimîzasyonên rûpela dayina fermanê çalak bikin','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Ji bo fermanên heyî yên ku li benda dravdana ji xerîdar in, sêwirana rûpela dravdana fermanê diguhezîne.','Add widget areas to the order pay page' => 'Herêmên widgetê li rûpela dravdana fermanê zêde bikin','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Van deverên widgetan têne bikar anîn ku li ser rûpela dravdana fermanê sembolên pêbaweriyê û nîşaneyên pêbaweriyê zêde bikin.','Thank you page & order details layout' => 'Spasiya rûpel û rêzika hûrguliyên fermanê','Order details optimizations' => 'Optimîzasyonên hûrguliyan ferman bikin','Enable thank you page and order details optimizations' => 'Rûpelê spas çalak bikin û xweşbîniyên hûrguliyan ferman bikin','Changes the layout of order details on the thank you page and account pages.' => 'Li ser rûpela spas û rûpelên hesabê layout hûrguliyên fermanê diguhezîne.','Enable order details customizations on email notifications' => 'Vebijarkên hûrguliyên fermanê li ser agahdariya e-nameyê çalak bikin','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Beşên nû nîşan bidin û rêza beşan li ser agahdariya e-nameyê biguhezînin. Şêwazên hûrguliyên fermanê yên li ser agahdariya e-nameyê nayê guhertin.','Thank you page' => 'Rûpelê spas','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Van vebijarkan bandorê li rûpela spasiyê dikin, ku wekî rûpelên fermanê hatine wergirtin an jî rûpelên pejirandina fermanê têne zanîn.','Order details layout' => 'Siparîşa hûrguliyên layout','Display the order details with wide layout on the thank you page' => 'Li ser rûpela spasiyê hûrguliyên fermanê bi sêwirana berfireh nîşan bidin','Add widget areas to the thank you page' => 'Herêmên widgetê li rûpela spasiyê zêde bikin','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Van deverên widgetan têne bikar anîn ku li ser rûpela spasiyê sembolên pêbaweriyê û nîşaneyên pêbaweriyê zêde bikin.','Order actions' => 'Order çalakiyên','Choose in which position to display the order actions.' => 'Hilbijêre ku di kîjan pozîsyonê de kiryarên fermanê nîşan bide.','Inside the order overview' => 'Di hundurê pêşandana fermanê de','After the order overview' => 'Piştî pêşandana fermanê','After order sections' => 'Piştî beşên fermanê','Order status' => 'Rewşa fermanê','Display the order status progress bar' => 'Barê pêşkeftina rewşa fermanê nîşan bidin','Choose in which position to display the section.' => 'Hilbijêre ku di kîjan pozîsyonê de beşê nîşan bide.','After the order overview and payment instructions' => 'Piştî pêşandana fermanê û talîmatên dravdanê','Before the order items section' => 'Berî beşa hêmanên fermanê','Inside the order items section' => 'Di hundurê beşa hêmanên fermanê de','After the order items section' => 'Piştî beşa hêmanên fermanê','On the sidebar' => 'Li kêlekê','Order downloads' => 'Siparîşa daxistinan','Gift message' => 'Peyama diyariyê','Tools' => 'Amûrên','Troubleshooting' => 'Çareserkirina pirsgirêkan','Debug options' => 'Vebijarkên Debug','Debug mode' => 'Moda Debug','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Bikaranîna moda debugê bandorê li performansa malperê dike. Tenê vê vebijarkê di dema çareserkirina pirsgirêkan de bikar bînin.','Load unminified assets' => 'Malên nenaskirî bar bikin','Enhanced select fields' => 'Zeviyên hilbijartî yên pêşkeftî','Fix automatic zoom-in on form fields' => 'Li ser zeviyên formê zoom-in otomatîk rast bikin','Set <code>font-size</code> inside form fields to 16px' => '<code>font-size</code> di hundurê qadên formê de 16 px destnîşan bikin','Fluid Checkout' => 'Fluid Checkout','Settings' => 'Settings','Support' => 'Alîkarî','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Ji PRO-yê nûve bikin</a> da ku vebijarkên bêtir vekin.','(PRO)' => '(PRO)','(experimental)' => '(ceribandinî)','Please verify your phone number.' => 'Ji kerema xwe jimara têlefona xwe verast bikin.','The Bluehost Plugin' => 'Pêveka Bluehost','Custom fields' => 'zeviyên Custom','Enable custom shipping email field' => 'Qada e-nameya şandina xwerû çalak bike','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Dema ku were çalak kirin, qada e-nameya barkirinê ya ji pêveka Bluehost dê li forma dravdanê were zêdekirin.','Captcha Pro by BestWebSoft' => 'Captcha Pro ji hêla BestWebSoft ve','Captcha position' => 'helwesta Captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Helwesta nîşankirina beşa captcha diyar bikin. Dibe ku hin pozîsyon li gorî celebê captcha bijartî nexebitin.','Selecting a pickup point is required before proceeding.' => 'Hilbijartina xalek hilgirtinê berî ku bidome pêdivî ye.','Pickup point' => 'Xala hilgirtinê','Pickup point not selected yet.' => 'Xala hilgirtinê hîn nehatiye hilbijartin.','Pickup point:' => 'Xala hilgirtinê:','Mailchimp for WooCommerce' => 'Mailchimp ji bo WooCommerce','Subscribe checkbox' => 'Qutiya kontrolê ya abonetiyê','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Helwesta qutiya kontrolê ya abonetiyê li ser rûpela danûstendinê bişopînin û her gav wê li ser gavê têkiliyê nîşan bidin','Before Shipping Address' => 'Berî Navnîşana Barkirinê','(originally "%s")' => '(bi eslê xwe &quot;%s&quot;)','After Shipping Address' => 'Piştî Navnîşana Shipping','Selecting a collection point is required when shipping with FermoPoint.' => 'Hilbijartina nuqteyeke berhevkirinê dema ku bi FermoPoint ve tê şandin hewce ye.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Ger were kontrol kirin xeletiyên di e-nameyê de ji bikarhêneran re agahdar dike. (Ji ber ku Fluid Checkout taybetmendiyê pêşkêş dike, ev taybetmendî hate neçalak kirin. Guhertinên vê vebijarkê dê bandor nebe)','Enable Mail Check: (disabled feature)' => 'Kontrolkirina Maîlê çalak bike: (taybetmendiya neçalak)','Carrier:' => 'Barkêş:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - Kirrûbirra E-nameyê WooCommerce','Sign up checkbox position' => 'Sign up helwesta checkbox','Move the sign up checkbox to the contact step' => 'Qutiya kontrolê ya qeydkirinê veguherînin qonaxa têkiliyê','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Dema ku were çalak kirin, qutiya kontrolê dê ji cîhê pêşandanê yê ku di mîhengên pêveka Sendinblue de hatî destnîşan kirin veguhezîne qonaxa têkiliyê.','Theme Betheme' => 'Mijara Betheme','Checkout progress' => 'Pêşveçûna kontrolê','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Ji Betheme beşa gavên danûstendinê derxînin li ser rûpelên drav, selik û fermanê.','Theme Fennik' => 'Mijara Fennik','Breadcrumbs' => 'Breadcrumbs','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Dema ku sernav û pêlava Fluid Checkout bikar tînin, beşa nanê ji mijara Fennik derxînin.','Theme Go' => 'Tema Go','My account layout' => 'Plansaziya hesabê min','Enable wide layout on "My account" page.' => 'Li ser rûpela &quot;Hesabê min&quot; plansaziya berfireh çalak bike.','Theme Impreza' => 'Mijara Impreza','Header' => 'Header','Spacing for site header at the checkout page (in pixels)' => 'Cihê ji bo sernavê malperê li rûpela danûstendinê (bi pixel)','Only applicable when using the Impreza theme header at the checkout page.' => 'Tenê dema ku sernavê mijara Impreza di rûpela danûstendinê de bikar bînin tê sepandin.','Theme Kapee' => 'Mijara Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Beşa gavên danûstendinê ji mijara Kapee li ser rûpelên drav, selik û fermanê derxînin.','Theme Porto' => 'Mijara Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Beşa gavên danûstendinê ji mijara Porto li ser rûpelên drav, selik û fermanê derxînin.','Theme Pressmart' => 'Mijara Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Beşa gavên danûstendinê ji mijara Pressmart li ser rûpelên drav, selik û fermanê derxînin.','Theme The Gem' => 'Mijara Gem','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Dema ku serî û pêlava Fluid Checkout bikar tînin, beşa gavên danûstendinê ji mijara Gem derxînin.','Theme Woodmart' => 'Mijara Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Dema ku sernav û pêlava Fluid Checkout bikar tînin, beşa gavên danûstendinê ji mijara Woodmart derxînin.','Checkout options' => 'Vebijarkên kontrolê','Disable the theme checkout options' => 'Vebijarkên danûstendina mijarê neçalak bike','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Vebijarkên wêneya hilberê, qada hejmarê, bişkojka jêbirin û girêdana rûpela hilberê ya ku ji hêla mijarê ve hatî zêdekirin nîşan dide ji hêla xwerû ve neçalak in.','Theme Atomion' => 'Mijara Atomion','Order progress' => 'Pêşkeftina fermanê','Display order progress from the theme' => 'Pêşkeftina fermanê ji mijarê nîşan bidin','Display the form field labels visible on the page' => 'Nîşaneyên qada formê yên ku li ser rûpelê têne xuyang kirin nîşan bidin','It is recommended to keep this option enabled for a better user experience.' => 'Tête pêşniyar kirin ku ji bo ezmûnek bikarhênerek çêtir vê vebijarkê çalak bihêlin.','Theme ZK Nito' => 'Mijara ZK Nito','Add extra fields to the checkout form' => 'Zeviyên zêde li forma danûstendinê zêde bikin','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Zeviyek e-name û têlefonê barkirinê ya zêde li beşa navnîşana barkirinê zêde dike.','Go to the home page' => 'Biçe ser rûpelê malê','Skip to content' => 'Skip nav naverokê','Create an account' => 'Hesabek çêbikin','Log in to your account' => 'Têkeve hesabê xwe','Already have an account?' => 'Jixwe hesabek heye?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Têkeve wekî %1$s. <a href="%2$s">Derkeve</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Ji bo fermana we rêjeyek bi tevahî %s heye. Bê peredana bêtir hewce ne.','Close and continue with checkout' => 'Girtin û bi danûstendinê re berdewam bikin','Continue' => 'Berdewamkirin','Parcel terminal' => 'Termînalê parselê','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Ev widget ji hêla Fluid Checkout ve hatî guhertin.</p><p> Dema ku Fluid Checkout bikar tîne, pêdivî ye ku rûpela danûstendinê kurtekoda bingehîn a WooCommerce <code>[woocommerce_checkout]</code> bikar bîne da ku bi rêkûpêk bixebite.</p><p> Ji bo bêtir agahdarî, biçin belgeya Fluid Checkout.</p>','Theme The7' => 'Mijara The7','Additional header sections' => 'beşên sernivîsê yên din','Output additional header sections if enabled in the theme settings.' => 'Ger di mîhengên mijarê de were çalak kirin beşên sernavê yên din derxînin.','More information' => 'Agahiyên bêtir','Pick a Locker' => 'Lokerek hilbijêre','Page template' => 'Şablona rûpelê','Use `Order confirmation` page template for block-based themes' => 'Ji bo mijarên li ser bingeha blokê, şablona rûpela `Piştrastkirina fermanê` bikar bînin','Only applies when using a block-based theme.' => 'Tenê dema ku mijarek li ser bingeha blokê tê bikar anîn derbas dibe.','WooCommerce Stripe Gateway' => 'Deriyê Xêza WooCommerce','Payment form' => 'Forma dravdanê','Apply styles to the Stripe payment form fields' => 'Şêwazan li ser qadên forma dravdanê ya Stripe bicîh bînin','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Dema ku were çalakkirin, Fluid Checkout dê şêwazên ku ji bo lihevhatina bi pêveka re hatine çêtirkirin bicîh bîne. Heke hûn şêwazên xwerû ji bo qadên forma dravdanê ya Stripe bikar tînin, dibe ku hûn bixwazin vê yekê neçalak bikin.','Theme Nyture' => 'Mijara Nûjen','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Dema ku Fluid Checkout tê bikaranîn, beşa gavên kontrolê ji mijara Nyture derxe.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Destûrê dide xerîdaran ku ji bo fermanên ku ji hêla rêveberê firotgehê ve bi destan hatine çêkirin an jî di dema kirînê de nehatine temam kirin, drav bidin.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Pêveka WooCommerce Checkout Manager ya Quadlayers bi Fluid Checkout re ne lihevhatî ye.','Company name field for billing address' => 'Qada navê şîrketê ji bo navnîşana fatûreyê','Change visibility for the company name field for the billing address section on the checkout form.' => 'Ji bo qada navê şîrketê ya beşa navnîşana fatûreyê li ser forma dravdanê, xuyabûna wê biguherîne.','Theme Bookshelf' => 'Refê Pirtûkan a Mijarê','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Dema ku Fluid Checkout tê bikar anîn, beşa gavên derxistinê ji mijara Bookshelf derxe.','Account password' => 'Şîfreya hesabê','An account will be created with the information provided at checkout when completing the order.' => 'Hesab dê bi agahdariya ku di dema qedandina fermanê de di kasayê de hatî dayîn were çêkirin.','Choose the style of the progress bar.' => 'Şêwaza xêza pêşketinê hilbijêre.','Bars' => 'Bar','Theme Ireca' => 'Theme Ireca','WooCommerce page layout' => 'Şêweya rûpela WooCommerce','Force wide layout on WooCommerce pages' => 'Nexşeya fireh li ser rûpelên WooCommerce ferz bike','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Ev yek piştrast dike ku beşa naverokê li ser rûpelên WooCommerce-ê, tevî rûpelên dravdanê, selikê, siparîşa wergirtî, dayîna siparîşê û hesabê, pir teng nebe.','WooCommerce Smart Coupons' => 'Kuponên Jîr ên WooCommerce','Position on checkout page' => 'Cihê li ser rûpela dravdanê','Choose where to display the available coupons section on the checkout page.' => 'Li ser rûpela dravdanê hilbijêrin ka beşa kuponên berdest li ku derê were nîşandan.','Before the progress bar' => 'Berî barika pêşketinê','After the progress bar' => 'Piştî barika pêşketinê','Before coupon codes section' => 'Berî beşa kodên kuponê','Format phone numbers according to the rules for each country.' => 'Hejmarên telefonê li gorî rêzikên her welatî format bikin.','Use precise phone number validation' => 'Verastkirina rast a hejmara têlefonê bikar bînin','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Ev taybetmendiyek ceribandinî ye û dibe ku di hemî sazkirinan de wekî ku tê hêvîkirin nexebite. Bi baldarî bikar bînin.','Phone number validation types used when precise validation is enabled.' => 'Cureyên pejirandina hejmarên telefonê yên ku dema pejirandina rast çalak e têne bikar anîn.','Mobile' => 'Hejî','Fixed line' => 'Xeta sabît','Toll free' => 'Bêpere','Contact' => 'Têkelî','Multi step' => 'Pir gav','2 columns' => '2 stûn','1 column' => '1 stûn','Before checkout steps' => 'Gavên berî kontrolkirinê','Or' => 'An','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Dema ku hûn nexşeya dravdanê ya <em>&quot;1 stûn&quot;</em> bikar tînin, ev vebijark her gav li ser <em>&quot;Berî gavên dravdanê&quot;</em> tê danîn û ji bo dîtina sermaseyê jî derbas dibe.','Position for the extra order summary section on mobile.' => 'Pozîsyona beşa kurteya fermana zêde li ser mobîl.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Vebijêrka <em>&quot;Li ser sernivîsa malperê&quot;</em> tenê dema ku sernivîsa bê-balkişandin tê bikar anîn derbas dibe.','On the site header (requires distraction-free header)' => 'Li ser sernivîsa malperê (sernivîsek bê balkişandin hewce dike)','Initial state for the expansible order summary section on mobile.' => 'Rewşa destpêkê ji bo beşa kurteya fermanê ya berfirehkirî li ser mobîl.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Em pêşniyar dikin ku ji ber hewcedariyên rêziknameyî, ji bo welatên jêrîn wekî <em>berfirehkirî</em> were danîn: <strong>Almanya</strong> , <strong>Avusturya</strong> , <strong>Swîsre</strong> , <strong>Hollanda</strong> , <strong>Polonya</strong> , <strong>Belçîka</strong> û <strong>Fransa</strong> .','Collapsed' => 'Hilweşiya','Expanded' => 'Berfirehkirî','Do not show' => 'Nîşan nede','yes' => 'erê','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Ger beşa navnîşana fatûreyê piştî beşa navnîşana barkirinê were nîşandan û qada telefona fatûreyê wekî &quot;pêwîst&quot; were danîn, dibe ku qada telefona barkirinê wekî &quot;pêwîst&quot; were ferzkirin. Ev ji bo piştrastkirina ku navnîşana barkirinê dikare li navnîşana fatûreyê were kopî kirin dema ku ew vebijark were hilbijartin, pêdivî ye, wekî din dibe ku xerîdar nikaribe forma dravdanê temam bike.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Ger beşa navnîşana fatûreyê berî beşa navnîşana şandinê were nîşandan û qada telefona şandinê wekî &quot;pêwîst&quot; were danîn, dibe ku qada telefona fatûreyê wekî &quot;pêwîst&quot; were ferzkirin. Ev ji bo piştrastkirina ku navnîşana şandinê dikare li navnîşana fatûreyê were kopî kirin dema ku ew vebijark were hilbijartin, pêdivî ye, wekî din dibe ku xerîdar nikaribe forma dravdanê temam bike.','Settings profiles' => 'Profîlên mîhengan','Settings profile' => 'Profîla mîhengan','You do not have permission to perform this action.' => 'Destûra te tune ku vê çalakiyê pêk bînî.','You do not have permission to activate plugins.' => 'Destûra te tune ku pêvekan çalak bikî.','Missing plugin.' => 'Plugin wenda ye.','Plugin activated.' => 'Plugin hate çalakkirin.','The following changes will be applied:' => 'Guhertinên jêrîn dê werin sepandin:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Ji Fluid Checkout 5.0 vir ve, mîheng bi awayên cuda têne tomarkirin. Vebijarkên kevn hîn jî di databasê de têne hilanîn da ku heke pêwîst be, daketin bo guhertoyên berê werin destûr kirin.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Dikana we nêzîkî 2 hefteyan e li ser mîhengên nû dixebite, ji ber vê yekê hûn dikarin vebijarkên kevn ên ku di databasa de hatine hilanîn paqij bikin. Ji kerema xwe not bikin ku piştî paqijkirinê, heke hûn hewce ne ku dakevin guhertoyên berê yên pêvekê, ew ê nirxên xwerû ji bo hemî mîhengan bikar bîne.','Fluid Checkout settings cleanup' => 'Paqijkirina mîhengên Fluid Checkout','Delete leftover options' => 'Vebijarkên mayî jê bibe','Help us improve Fluid Checkout' => 'Alîkariya me bikin ku em Fluid Checkout baştir bikin','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Raporên jîngeha malperê yên anonîm bi Fluid Checkout re parve bikin da ku piştgiriyek zûtir bistînin û ji me re bibin alîkar ku em lihevhatinê baştir bikin û bandorê bipîvin. Tu daneyên xerîdar, bikarhêner an hesas nayên nav kirin. Hûn dikarin her dem ji mîhengên Amûran hilbijêrin ka çi were parve kirin.','Enable site environment reports' => 'Raporên jîngeha malperê çalak bike','Review settings' => 'Mîhengan binirxîne','This preview has expired. Reload the admin page to start a new preview.' => 'Ev pêşdîtin qediyaye. Ji bo destpêkirina pêşdîtinek nû rûpela rêveberiyê ji nû ve bar bike.','Preview expired' => 'Pêşdîtin qediya','Orders cannot be placed in the preview.' => 'Siparîş di pêşdîtinê de nayên danîn.','Logging in is not available in the preview.' => 'Têketin di pêşdîtinê de ne berdest e.','Accounts cannot be created in the preview.' => 'Di pêşdîtinê de hesab nayên afirandin.','Requests to other sites are blocked in the preview.' => 'Daxwazên ji bo malperên din di pêşdîtinê de têne astengkirin.','Processing…' => 'Xebitandinî…','Something went wrong. Please try again.' => 'Tiştek xelet çû. Ji kerema xwe dîsa biceribînin.','Activate plugin' => 'Pêveka çalak bike','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - Pakêta temam a dravdanê','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Hemû taybetmendiyên PRO + hemû pêvek, yek biha. Şablonên sêwiranê, rûpelên sepet û siparîşên wergirtî yên çêtirkirî, hevahengkirina hesaban, û gelek tiştên din.','Optimized order pay page' => 'Rûpela dayîna fermanê ya çêtirînkirî','Express checkout buttons from supported payment methods' => 'Bişkokên dravdana bilez ji rêbazên dravdanê yên piştgirîkirî','Delayed account creation' => 'Derengketina çêkirina hesabê','Address autocomplete with Google Maps APIs' => 'Bi API-yên Nexşeyên Google-ê ve oto-temamkirina navnîşanê','Multiple saved addresses with the address book' => 'Gelek navnîşanên tomarkirî bi pirtûka navnîşan re','EU-VAT assistant' => 'Alîkarê EU-VAT','Hide this section' => 'Vê beşê veşêre','Learn more' => 'Bêtir hîn bibin','Get early access' => 'Gihîştina zû bistînin','Activate add-on' => 'Pêveka çalak bike','Get more out of your checkout journey' => 'Ji rêwîtiya xwe ya dravdanê bêtir sûd werbigirin','Test API key' => 'Mifteya API-yê ya ceribandinê','Guided setup' => 'Sazkirina rêberkirî','Options' => 'Vebijêrk','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Di <a href="%s">vebijarkên dravdanê</a> de nexşe û sêwiranê saz bikin.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Derbaskirina mêvanan çalak bike û/an <a href="%s">mîhengên hesabên xerîdaran</a> binirxîne.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Rûpelên <a href="%1$s">sepet</a> , <a href="%2$s">spasdarî</a> û <a href="%3$s">dayîna fermanê</a> yên çêtirkirî çalak bike.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Ji Nexşeyên Google-ê <a href="%s">otomatîkîkirina navnîşanê</a> çalak bike.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Bi <a href="%s">pirtûka navnîşanan</a> ve gelek navnîşanên tomarkirî çalak bike.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Kontrol bike ka ji bo mijarê an pêvekên din ên ku te saz kirine <a href="%s">vebijarkên entegrasyonê</a> hene.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Piştgiriyek zûtir bistînin û ji me re bibin alîkar ku em lihevhatinê baştir bikin û bandorê bipîvin. <a href="%s">Şopandina karanînê ji mîhengên amûran çalak bikin</a> .','Missing settings tab.' => 'Tabloya mîhengan wenda ye.','Getting started' => 'Destpêkirin','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Mezin! Rûpela we ya dravdanê niha li ser Fluid Checkout dixebite.</strong> Li vir çend gav hene ku hûn dest pê bikin:','Completed' => 'Qediya','Preview report data' => 'Pêşdîtina daneyên raporê','Send now' => 'Niha bişîne','Auto-detect' => 'Otomatîk tespîtkirin','Afrikaans' => 'Afrîkansî','Albanian' => 'Albanî','Amharic' => 'Amharîkî','Arabic' => 'Erebî','Armenian' => 'Ermenî','Azerbaijani' => 'Azerbaycanî','Basque' => 'Baskî','Belarusian' => 'Belarûsî','Bengali' => 'Bengalî','Bosnian' => 'Bosnayî','Bulgarian' => 'Bûlgarî','Burmese' => 'Bîrmanî','Catalan' => 'Katalanî','Chinese' => 'Çînî','Chinese (Simplified)' => 'Çînî (Hêsankirî)','Chinese (Hong Kong)' => 'Çînî (Hong Kong)','Chinese (Traditional)' => 'Çînî (Kevneşopî)','Croatian' => 'Xirwatî','Czech' => 'Çekî','Danish' => 'Danîmarkî','Dutch' => 'Holandî','English' => 'Îngilîzî','English (Australian)' => 'Îngilîzî (Awistralyayî)','English (Great Britain)' => 'Îngilîzî (Brîtanyaya Mezin)','Estonian' => 'Estonî','Farsi' => 'Farisî','Finnish' => 'Fînlandî','Filipino' => 'Filîpînî','French' => 'Fransî','French (Canadian)' => 'Fransî (Kanadayî)','Galician' => 'Galîsyayî','Georgian' => 'Gurcî','German' => 'Almanî','Greek' => 'Yewnanî','Gujarati' => 'Gujaratî','Hebrew' => 'Îbranî','Hindi' => 'Hindî','Hungarian' => 'Macarî','Icelandic' => 'Îzlandî','Indonesian' => 'Îndonezî','Italian' => 'Îtalî','Japanese' => 'Japonî','Kannada' => 'Kanadayî','Kazakh' => 'Qazakî','Khmer' => 'Khmer','Korean' => 'Koreyî','Kyrgyz' => 'Qirgizî','Lao' => 'Laoyî','Latvian' => 'Letonî','Lithuanian' => 'Lîtvanyayî','Macedonian' => 'Makedonî','Malay' => 'Malayî','Malayalam' => 'Malayalamî','Marathi' => 'Maratî','Mongolian' => 'Moxolî','Nepali' => 'Nepalî','Norwegian' => 'Norwêcî','Polish' => 'Polandî','Portuguese' => 'Portekizî','Portuguese (Brazil)' => 'Portekîzî (Brezîlya)','Portuguese (Portugal)' => 'Portekîzî (Portekîz)','Punjabi' => 'Pencabî','Romanian' => 'Romanyayî','Russian' => 'Rûsî','Serbian' => 'Sirbî','Sinhalese' => 'Sînhalî','Slovak' => 'Slovakî','Slovenian' => 'Slovenî','Spanish' => 'Îspanyolî','Spanish (Latin America)' => 'Spanî (Amerîkaya Latîn)','Swahili' => 'Swahîlîyî','Swedish' => 'Swêdî','Tamil' => 'Tamîlî','Telugu' => 'Teluguyî','Thai' => 'Thayîkî','Turkish' => 'Tirkî','Ukrainian' => 'Ûkraynî','Urdu' => 'Ûrdûyî','Vietnamese' => 'Vîetnamî','Zulu' => 'Zulû','Google address autocomplete' => 'Otomatîkkirina navnîşana Google','Google Places API version' => 'Versiyona API-ya Cihên Google-ê','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Guhertoya API-ya Cihên Google-ê hilbijêrin ku hûn bikar bînin. Em pêşniyar dikin ku hûn zûtirîn dem derbasî API-ya Cihên nû bibin.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Em pêşniyar dikin ku hûn &quot;Places API (Nû)&quot; bikar bînin. Ji 1ê Adara 2025an pê ve, Google dê guhertoya &quot;Places API (Legacy)&quot; biguhezîne rewşa Legacy, ev tê vê wateyê ku hûn êdî nikaribin vê xizmetê ji bo mifteyên API-yên nû çalak bikin û ew guhertoya API-yê di dawiyê de êdî peyda nabe. Hesabên heyî yên ku berê API-ya Legacy bikar tînin dikarin bêyî astengiyan berdewam bikin.','(Recommended)' => '(Pêşniyarkirî)','Google API key' => 'Kilîda API-ya Google-ê','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Kilîta API-ya xwe ya Google-ê bipêçe û bişkoja ceribandinê bikar bîne da ku piştrast bikî ku ew ji bo vê malperê dixebite. Piştrast bike ku kilît ji bo domaina te derbasdar û destûrdayî ye, wekî din dibe ku qada navnîşanê were asteng kirin û rê li ber xerîdaran bigire ku fermanên xwe temam bikin.','Enable Google address autocomplete' => 'Otomatîkkirina navnîşana Google çalak bike','Enable address autocompletion using the Google Maps APIs.' => 'Bi karanîna API-yên Nexşeyên Google-ê, temamkirina otomatîkî ya navnîşanê çalak bike.','Google API language' => 'Zimanê API-ya Google-ê','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Ev ziman dê ji bo nîşandana pêşniyarên navnîşanên Google Places API were bikar anîn û navnîşan jî dê bi vî zimanî bixweber werin temamkirin.','Result types' => 'Cureyên encaman','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Ji bo qebûlkirina her cure encaman, ku bi gelemperî encamên hevaheng ên çêtir dide, vala bihêlin. <a href="%s" target="_blank">Ji bo bêtir agahdarî li belgeyan binêre</a> .<br> Heta 5 cureyên encamên lêgerîna navnîşanê hilbijêrin da ku li ser qadên oto-temamkirina navnîşanê werin vegerandin.<br> Ji bo bêtir agahdarî li ser <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">celebên piştgirîkirî,</a> serdana belgeyên Nexşeyên Google bikin.','Result types (Legacy API)' => 'Cureyên encaman (API-ya Kevneşopî)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Dema ku Places API (Legacy) tê bikar anîn, divê kîjan celeb encamên lêgerîna navnîşanê werin vegerandin.<br> Ji bo bêtir agahdarî li ser <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">celebên piştgirîkirî</a> , serdana belgeyên API-ya Legacy Google Places bikin.','Company fields' => 'Zeviyên şîrketê','Enable autocomplete for the company name if available' => 'Heke hebe, ji bo navê şîrketê temamkirina otomatîk çalak bike','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Dema ku ji API-yên Nexşeyên Google-ê tê vegerandin, temamkirina otomatîkî ya qada şîrketê bi agahdariya navê şîrketê çalak bike.','Business search' => 'Lêgerîna karsaziyê','Enable search for businesses in the company field' => 'Lêgerîna karsaziyan di qada şîrketê de çalak bike','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Dema nivîsandina qada şîrketê, pêşniyara navnîşanên girêdayî karsaziyekê çalak bike, dûv re dema ku karsaziyek ji pêşniyaran tê hilbijartin, hemî qadên navnîşanê bixweber temam bike.','Company result types' => 'Cureyên encamên şîrketê','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Heta 5 cureyên encamên lêgerîna navnîşanê hilbijêrin da ku li ser qadên şîrketa oto-temamkirinê vegerin.<br> Nirxa pêşniyarkirî <code>establishment</code> e, ku piraniya celebên karsaziyan dihewîne.<br> Ji bo qebûlkirina her cure encaman, tevî encamên ku ne bi karsaziyan ve girêdayî ne, vala bihêlin.<br> Ji bo bêtir agahdarî li ser <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">celebên piştgirîkirî,</a> serdana belgeyên Nexşeyên Google bikin.','Google logo' => 'Logoya Google','Show text and logo "Powered by Google"' => 'Nivîs û logoya &quot;Powered by Google&quot; nîşan bide','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Dema ku were kontrolkirin, nivîs û logoya &quot;Powered by Google&quot; dê li binê qutiya pêşniyarên oto-temamkirina navnîşanê werin nîşandan.','Brasil API address autocomplete' => 'Otomatîkkirina navnîşana API-ya Brezîlyayê','Brasil API' => 'APIya Brezîlyayê','Enable Brasil API address autocomplete for CEP fields' => 'Ji bo qadên CEP-ê, temamkirina otomatîk a navnîşana API-ya Brasil çalak bike','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Ji bo wergirtin û dagirtina otomatîkî ya navnîşanan bi karanîna qada CEP/Postcode, Brasil API bikar bînin. Tenê ji bo navnîşanên Brezîlyayê têkildar e.','API version' => 'Guhertoya API-yê','Choose which version of the Brasil API CEP method to use.' => 'Guhertoya rêbaza Brasil API CEP hilbijêre ku dixwazî bikar bînî.','Address book migration' => 'Veguhestina pirtûka navnîşanan','WooCommerce addresses' => 'Navnîşanên WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Navnîşanên şandin û fatûreyê yên heyî ji WooCommerce kopî bikin nav pirtûka navnîşanên xerîdaran.','Enable the address book feature' => 'Taybetiya pirtûka navnîşanan çalak bike','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Destûrê bide xerîdaran ku gelek navnîşanan tomar bikin û navnîşana xwerû ya ku ji bo şandin û fatûreyê were bikar anîn destnîşan bikin.','Address labels' => 'Etîketên navnîşanê','Allow customers to add a custom label for each address' => 'Destûrê bide xerîdaran ku ji bo her navnîşanê etîketek xwerû lê zêde bikin','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Etîketên navnîşanê ji bo xerîdaran hêsantir dikin ku navnîşanên xwe yên tomarkirî ji hev cuda bikin (wek mînak: &quot;Mala Dayikê&quot;). Etîketên navnîşanê tenê ji bo xerîdaran taybet in, û li ser rûpela hûrguliyên fermanê an fatûreyan nayên nîşandan an çapkirin.','Display layout' => 'Şêweya nîşandanê','Choose how saved addresses are displayed at checkout and on the cart.' => 'Hilbijêre ka navnîşanên tomarkirî çawa di qonaxa dawî ya kirînê û li ser selikê de werin nîşandan.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Di qonaxa qedandinê û li ser selikê de derbas dibe. Navnîşanên tomarkirî yên li ser rûpela hesabê her gav şêwaza kartan bikar tînin.','Address cards' => 'Kartên navnîşanê','Address list' => 'Lîsteya navnîşanan','Dropdown field' => 'Qada daketî','Address search' => 'Lêgerîna navnîşanê','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Dema ku xerîdar bi kêmanî ev hejmara navnîşanên tomarkirî hebe, fîltera lêgerîna navnîşanê li ser pêşiyê nîşan bide.','Not used when display layout is set to dropdown field.' => 'Dema ku sêwirana nîşandanê li ser qada daketî were danîn, nayê bikar anîn.','Addresses' => 'Navnîşan','Enable cart page optimizations to see more options' => 'Ji bo dîtina vebijarkên bêtir, çêtirkirina rûpela selikê çalak bike','Sticky order summary' => 'Kurteya fermana zeliqok','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Cihê ku beşa kodên kuponê li ser rûpela selikê tê de were nîşandan hilbijêre. Tenê dema ku selika AJAX çalak be derbasdar e, û heke karanîna kodên kuponê di mîhengên WooCommerce de çalak be.','Layout of cross-sell' => 'Nexşeya firotina xaçerêyî','Cross-sells displayed' => 'Firotinên xaçerêyî yên hatine nîşandan','Items' => 'Tişt','Cart page optimization' => 'Optimîzasyona rûpela sepetê','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Sepeta xwe heman sêwirana zelal û li ser veguherînê-navendî wekî dravdana xwe bidin.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Ji bo rêwîtiyek kirînê ya domdar, sêwirana selikê bi rûpela dravdanê re li hev bikin.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Sepetê her tim di paşxaneyê de nûvekirî bihêle, dema ku hejmar diguherin rûpel bi tevahî nayê barkirin.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Kodên kuponê, şandin û firotina xaçerê tam li cihê ku ew çêtirîn veguherînin bicîh bikin.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Kurteya fermanê dema gerandinê xuya bike, û li cihên ku kirrûbir hewceyî piştrastbûnê ne, sembolên baweriyê lê zêde bike.','Columns' => 'Stûn','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Şêwazên giştî ji bo gavên dravdanê, kurteya fermanê û beşên din. Ji bo rûpelên din ên dravdanê, sepetê, spas (ferman hat wergirtin), û dîtina fermanê derbas dibe.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Dema ku hûn nexşeya <em>&quot;1 stûn&quot;</em> bi şablona sêwirana <em>&quot;Parvekirin&quot;</em> re bikar tînin, stûnek rast tenê tê xuyang kirin ger qada widgetê ya panela kêlekê ya rûpelê çalak be (Bendê Kêşanê, Panela Kêşanê, an Panela Kêşana Siparîşê). Wekî din, rûpel bi şêwazên Parvekirinê wekî stûnek yekane dimîne.','Split column background' => 'Paşxaneya stûnê ya parçekirî','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Rengê paşxaneyê ji bo stûna duyemîn a sêwirana dabeşkirî hilbijêre. Ji bo bikaranîna rengê paşxaneyê yê kurteya rêzê vala bihêle.','Page templates' => 'Şablonên rûpelê','Checkout template' => 'Şablona dahatê','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Ji bo kêmtir bala mirovan di dema kirînê de tê pêşniyarkirin. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Lêkolîna li ser terikandina selikê bixwînin</a> .','Sticky progress bar' => 'Barika pêşketinê ya zeliqok','Progress bar style' => 'Şêwaza barika pêşveçûnê','Order totals' => 'Hemûya fermanan','Background color' => 'Rengê paşxaneyê','Action link' => 'Girêdana çalakiyê','Mobile order summary' => 'Kurteya fermana mobîl','Mobile initial state' => 'Rewşa destpêkê ya mobîl','Enable editing cart items at checkout' => 'Guherandina tiştên sepetê di dema kirînê de çalak bike','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Destûrê bidin xerîdaran ku mîqdarên hilberan biguherînin an tiştan rasterast li rûpela dravdanê derxînin.','Cart item errors' => 'Xeletiyên babetên sepetê','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Tenê dema ku koda kuponê wekî beşek cuda li ser rûpelên kasayê an selikê tê xuyang kirin derbas dibe, û heke karanîna kodên kuponê di mîhengên WooCommerce de çalak be.','Coupon codes position' => 'Cihê kodên kuponê','Apply coupon button' => 'Bişkoka kuponê bicîh bîne','Select style of the "apply coupon" button.' => 'Şêwaza bişkoka &quot;kuponê bi kar bîne&quot; hilbijêre.','Address line 2' => 'Rêza navnîşanê 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Ev mîheng di navbera beşên Dravdanê û Wergirtina Herêmî de tê parvekirin. Li ser beşa Wergirtina Herêmî, ew her weha biryar dide ka hilbijêra Şandin/Wergirtinê di hundurê beşa rêbaza şandinê de (berî navnîşanê) an wekî beşek cuda (piştî) tê xuyang kirin.','Customer accounts' => 'Hesabên xerîdaran','Guest checkout' => 'Derketina ji mêvanan','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Vebijarkên kirêkirina mêvan, têketin û çêkirina hesabê ji rûpela mîhengên Hesabên WooCommerce. Ew ji bo rehetiya we li vir têne birêvebirin, û ji ber vê yekê hûn dikarin nirxên cûda ji bo her profîla mîhengan bikar bînin.','Allow customers to checkout without an account' => 'Destûrê bide xerîdaran ku bêyî hesabê drav bidin','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => 'Ji ber vê yekê <strong>tê pêşniyarkirin</strong> ku ji xerîdaran neyê xwestin ku di dema kirînê de hesabek çêbikin an têkevinê, ku ev dikare rêjeyên veguherînê kêm bike.','When disabled, customers must log in or create an account to complete the purchase.' => 'Dema ku neçalak be, xerîdar divê têkevinê an hesabê xwe çêbikin da ku kirînê temam bikin.','Login at checkout' => 'Têkeve di kasayê de','Enable log-in during checkout' => 'Di dema kirînê de têketinê çalak bike','Show a link for returning customers to log in from the checkout page.' => 'Ji bo xerîdarên vegeriyayî girêdanek nîşan bide da ku ji rûpela dravdanê têkevinê.','Account creation' => 'Çêkirina hesabê','Allow customers to create an account during checkout' => 'Destûrê bidin xerîdaran ku di dema kirînê de hesabek çêbikin','Customers can create an account before placing their order.' => 'Xerîdar dikarin berî ku siparîşa xwe bidin hesabê xwe çêbikin.','Allow customers to create an account from the My account page' => 'Destûrê bide xerîdaran ku ji rûpela Hesabê Min hesab çêbikin','Customers can register a new account from the My account page.' => 'Xerîdar dikarin ji rûpela Hesabê Min hesabê nû tomar bikin.','Username' => 'Navê bikarhêner','Generate from customer\'s name' => 'Ji navê xerîdar çêbikin','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => 'Ji bo ku ji xerîdaran neyê xwestin ku di dema kirînê de navekî bikarhêner hilbijêrin, <strong>tê pêşniyar kirin</strong> , ku ev dikare rêjeyên veguherînê kêm bike.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Navê bikarhêner ji navê xerîdar, an jî dema ku navek neyê bikar anîn, ji navnîşana e-nameyê tê çêkirin.','Password' => 'Şîfre','Send password setup link' => 'Girêdana sazkirina şîfreyê bişîne','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Tête pêşniyar kirin</strong> da ku ji xerîdaran neyê xwestin ku di dema kirînê de şîfreyek saz bikin, ku ev dikare rêjeyên veguherînê kêm bike.','Customers receive an email to create their password securely.' => 'Xerîdar ji bo afirandina şîfreya xwe bi ewlehî e-nameyek distînin.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Bila xerîdarên qeydkirî bêyî têketinê dravdanê temam bikin û dema ku agahdariya têkiliyê li hev bike, fermanê bi hesabê xwe yê heyî ve girêbidin.','Existing account message' => 'Peyama hesabê heyî','Let customers create an account after placing their order, from the thank you page.' => 'Bila xerîdar piştî ku fermana xwe didin, ji rûpela spasdariyê hesabê xwe çêbikin.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Vebijarkên di vê beşê de dema ku kirîna mêvan û hevahengkirina hesabê çalak in hene. Her du taybetmendiyên jorîn çalak bikin da ku afirandina hesabê ya derengmayî mîheng bikin.','Enable delayed account creation' => 'Çêkirina derengmayî ya hesabê çalak bike','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Dema ku hem derketina mêvan û hem jî hevahengkirina hesaban çalak in, derengxistina afirandina hesabê çalak bike.','Section position' => 'Cihê beşê','Before customer details section' => 'Berî beşa hûrguliyên xerîdar','After customer details section' => 'Piştî beşa hûrguliyên xerîdar','Account creation benefits' => 'Feydeyên çêkirina hesabê','Leaving the field empty will display the default text.' => 'Ger qadê vala bihêlin dê nivîsa xwerû were xuyang kirin.','Inline buttons' => 'Bişkokên rêzkirî','Required fields' => 'Qadên pêwîst','Enable gift message fields at checkout' => 'Qadên peyama diyariyê di dema kirînê de çalak bike','Expanded gift message' => 'Peyama diyariyê ya berfireh','Display gift message field always expanded' => 'Qada peyama diyariyê ya herdemî nîşan bide berfireh bûye','Gift message in order details' => 'Peyama diyariyê di hûrguliyên fermanê de','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Niha li ser vê beşê entegrasyon tune ne. Vebijarkên têkildarî her pêvek û mijarê tenê dema ku ew pêvek an mijar were çalak kirin dê li vir xuya bibin.','Phone fields' => 'Zeviyên telefonê','Field visibility' => 'Dîtina zeviyê','Field position' => 'Cihê zeviyê','Phone country code & validation' => 'Koda welatê telefonê û pejirandin','Country' => 'Welat','Enable country on phone fields' => 'Welat li ser qadên telefonê çalak bike','Filter countries for shipping or billing' => 'Welatan ji bo şandin an fatûreyê fîltre bikin','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Hilbijêra welat li ser her qada telefonê bi welatên ku ji bo şandin an fatûrekirinê li firotgeha we destûr in ve sînordar bike.','Validation' => 'Tesdîqkirin','Enable simple validation based on country rules' => 'Tesdîqkirina hêsan li gorî qaîdeyên welat çalak bike','Checks that the phone number is valid for the selected country, including country code and length.' => 'Kontrol dike ka jimara telefonê ji bo welatê bijartî derbasdar e, tevî koda welat û dirêjahiya wê.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Kontrol bike ka hejmar ji bo welatê bijartî cureyekî mobîl, xeta sabît, an cureyekî din ê pejirandî ye an na. Dibe ku hin hejmarên derbasdar red bike.','Validation types' => 'Cureyên pejirandinê','Placeholders' => 'Cihgir','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Niha tu mifteyên lîsansê ji bo birêvebirinê tune ne. Dema ku pêvekek an pêvekek Fluid Checkout-ê ya lîsanskirî çalak be, mifteyên lîsansê dê li vir xuya bibin.','Default delivery type' => 'Cureyê radestkirinê yê xwerû','Choose which delivery type will be selected by default.' => 'Hilbijêre ka kîjan celeb radestkirin dê bi xwerû were hilbijartin.','Shipping zone fields' => 'Zeviyên herêma barkirinê','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Hilbijêre ka kîjan qad dê ji bo qadên fîltera herêma şandina hilgirtinê ya herêmî werin nîşandan. Ji bo nîşandana hemî vebijarkên berdest vala bihêlin.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Ev qad dê wekî fîlterek ji bo rêbazên şandina herêmî werin nîşandan. Dibe ku hin qad hîn jî di qonaxa kirînê de xuya bibin dema ku li vir neyên hilbijartin, heke pêvekên lihevhatî hewce bikin ku ew bi rêkûpêk bixebitin.','Order shipping address' => 'Navnîşana şandina siparîşê','Order pay page optimization' => 'Optimîzasyona rûpela dravdana fermanê','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Ji bo siparîşên nehatine dayîn jî heman sêwirana zelal û li ser veguherînê-navendî wekî ya qonaxa dawî bidin.','Optimize the layout of the order pay page for orders pending payment.' => 'Ji bo fermanên ku li benda dayinê ne, sêwirana rûpela dayîna fermanan çêtir bikin.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Ji bo rêwîtiyek kirînê ya domdar, ezmûna dayîna fermanê bi kaseya xwe re bidin ber hev.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Sembolên baweriyê û nîşanan li cihê ku kirrûbir berî dravdanê hewceyê piştrastbûnê ne zêde bikin.','Thank you page optimization' => 'Spas dikim baştirkirina rûpelê','Make the thank you page and order details clearer for customers after they buy.' => 'Rûpela spasdariyê û hûrguliyên siparîşê piştî kirînê ji bo xerîdaran zelaltir bikin.','Optimize the thank you page and account order details with a clearer layout.' => 'Rûpela spasdariyê û hûrguliyên fermana hesabê bi sêwiraneke zelaltir baştir bikin.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Pêşveçûna rewşa fermanê, çalakî, dakêşan û notan li cihê ku watedar in nîşan bide.','Customize order details sections on email notifications.' => 'Beşên hûrguliyên fermanê li ser agahdariyên e-nameyê xweş bikin.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Sembolên baweriyê û nîşanan li cihê ku kirrûbir piştî kirînê hewceyê piştrastbûnê ne zêde bikin.','Email notifications' => 'Agahdariyên e-nameyê','Enable thank you page and order details optimizations to see more options' => 'Ji bo dîtina vebijarkên bêtir, çêtirkirina rûpela spasdariyê û hûrguliyên fermanê çalak bike','Use wide layout on thank you page' => 'Li ser rûpela spasdariyê şêwaza fireh bikar bînin','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Ev vebijêrk bandorê li ser rûpela spasdariyê dikin, hûrguliyên fermanê li ser rûpelên hesabê û agahdariyên e-nameyê dibînin.','Save settings' => 'Mîhengan tomar bike','Docs' => 'Belge','Cart' => 'Ereboka destan','Thank you' => 'Sipas ji were','Address autocomplete' => 'Otomatîkkirina navnîşanê','Trust badges' => 'Nîşanên baweriyê','You do not have permission to save these settings.' => 'Destûra te tune ku van mîhengan tomar bikî.','Invalid save request.' => 'Daxwaza tomarkirinê nederbasdar e.','Your settings have been saved.' => 'Mîhengên te hatine tomarkirin.','Saving...' => 'Tê tomarkirin...','Settings could not be saved. Please try again.' => 'Mîheng nehatin tomarkirin. Ji kerema xwe dîsa biceribînin.','Dismiss notice' => 'Agahdariyê red bike','Open settings menu' => 'Menûya mîhengan veke','Close settings menu' => 'Menûya mîhengan bigire','Preview' => 'Pêşnerîn','Expand preview' => 'Pêşdîtinê berfireh bike','Collapse preview' => 'Pêşdîtinê bigire','Show header and footer' => 'Sernivîs û jêrnivîsê nîşan bide','Hide header and footer' => 'Sernivîs û jêrnivîsê veşêre','Page preview' => 'Pêşdîtina rûpelê','Preview viewport' => 'Pêşdîtina dîmenderê','Tablet' => 'Heb','Desktop' => 'Sermase','Preview width' => 'Firehiya pêşdîtinê','Decrease width' => 'Kêmkirina firehiyê','Preview width in pixels' => 'Firehiya pêşdîtinê bi pîkselan','Increase width' => 'Firehiyê zêde bike','Preview as' => 'Pêşdîtin wekî','Guest' => 'Mêvan','Logged in' => 'Têketî','Preview page' => 'Rûpela pêşdîtinê','Expand preview for a closer look' => 'Ji bo nihêrînek nêzîktir pêşdîtinê berfireh bike','Available with %s.' => 'Bi %s peyda dibe.','Turn them on' => 'Wan vekin','Optimizations for this page are turned off. %s to preview the page.' => 'Baştirkirin ji bo vê rûpelê hatine girtin. %s ji bo pêşdîtina rûpelê.','%s preview' => 'Pêşdîtina %s','Isolated session · nothing is saved' => 'Danişîna îzolekirî · tiştek nehatiye tomarkirin','Usage tracking' => 'Şopandina Bikaranînê','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Raporên jîngeha malperê yên ne-hesas bişînin da ku alîkariya Fluid Checkout bikin ku lihevhatinê baştir bike. Rapor nayên şandin heya ku di vebijarkên li jêr de neyên çalak kirin.','Send usage tracking reports to Fluid Checkout' => 'Raporên şopandina karanînê ji Fluid Checkout re bişînin','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Ev rapor alîkariya me dikin ku em lihevhatin û piştgiriya malpera we baştir bikin û dema ku çalak bibin heftane têne şandin.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Ti daneyên xerîdar, bikarhênerê rêveber, an jî ti daneyên din ên hesas di raporê de cih nagirin.','Basic environment info' => 'Agahiyên bingehîn ên jîngehê','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Agahiyên lîsteya WordPress, PHP, WooCommerce, mijar û pêvekan. Dema ku rapor çalak be, her tim tê de hene. Alîkariya me dike ku em hawîrdora ku malpera we tê de dixebite fam bikin.','Plugin settings' => 'Mîhengên pêvekê','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Mîhengên pêveka Fluid Checkout dişîne da ku ji bo daxwazên piştgiriyê bibe alîkar û ji me re dibe alîkar ku em fêm bikin ka hûn çawa pêvekên me bikar tînin.','Coming soon' => 'Hema têm','Sales metrics' => 'Metrîkên firotanê','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Jimara fermanên mehane û firotina giştî ya salek berî sazkirina Fluid Checkout heta îro. Alîkariya me dike ku em fêm bikin ka hûn bi pêvekên me yên sazkirî bêtir pere qezenc dikin an na. Tu daneyên xerîdar an bikarhêner nayên şandin.','Utilities' => 'Xizmetguzarî','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Li şûna <code>select2</code> pêkhateyên daketî yên <code>TomSelect</code> bikar bînin','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect pêkhateyeke hilbijartina daketî ya hêsantir e ku ji Select2 kêmtir meyla xeletiyan heye, di heman demê de heman fonksiyonê pêşkêş dike.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Mezinahiya tîpên di nav qadên forman de li ser rûpelên ku ji hêla vê pêvekê ve hatine çêtirkirin wekî 16px destnîşan dike da ku dema ku li ser cîhazên piçûk bi qadên forman re têkilî daynin, ji nêzîkbûna otomatîk dûr bikeve.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari û gerokên din dikarin li ser cîhazên mobîl bixweber zoom bikin da ku xwendina nivîsê hêsantir bibe dema ku mezinahiya tîpan ji 16px piçûktir be.','Enable script processing tracking on the browser console.' => 'Şopandina pêvajoya skrîptê li ser konsola gerokê çalak bike.','Unminified assets' => 'Mal û milkên nemînîzekirî','Google Maps scripts' => 'Skrîptên Nexşeyên Google-ê','Do not remove duplicate Google Maps scripts' => 'Skrîptên Nexşeyên Google-ê yên dubare jê neke','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Dema ku çalak be, skrîptên Nexşeyên Google-ê yên dubare NAYÊN rakirin, ku ev dikare bibe sedema xeletiyan û pirsgirêkên performansê. Tenê vê vebijarkê dema çareserkirina pirsgirêkan bikar bînin.','Widget areas' => 'Herêmên Widgetan','Last step on mobile' => 'Pêngava dawî li ser mobîl','Display widgets only at last step on mobile' => 'Widgetan tenê di gava dawî de li ser mobîl nîşan bide','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Widgetên nîşana baweriyê ya dravdanê tenê dema ku gava dawîn a dravdanê li ser cîhazên mobîl tê dîtin nîşan bide','Standard' => 'Rêzan','VAT number field' => 'Qada hejmara VATê','Add a VAT number field to the billing form.' => 'Qada jimara VAT-ê li forma fatûreyê zêde bikin.','Field label' => 'Etîketa zeviyê','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Etîketa qada hejmara VATê (ango hejmara VATê) destnîşan bike. Li ser malperên pirzimanî, çêtir e ku ev qadê vala bimîne û rêza orîjînal were wergerandin.','VAT Number' => 'Hejmara VATê','EU-VAT' => 'YE-VAT','Enable the VAT number field to see more options' => 'Ji bo dîtina vebijarkên zêdetir, qada hejmara VAT-ê çalak bike','VAT validation' => 'Pejirandina VATê','Validate VAT number field for EU-VAT during checkout' => 'Di dema kirînê de qada hejmara VAT-ê ji bo EU-VAT-ê piştrast bike','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Kontrol dike ka Hejmara VAT-ê ya hatî dayîn hejmareke VAT-ê ya derbasdar e ku li ser Databasa VIES-a Ewropî (Pergala Guhertina Agahiyên VAT-ê) hatî tomar kirin.','Shop VAT number' => 'Hejmara VAT ya dikanê','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Hejmara VAT ya dikanê ku ji bo daxwaza pejirandina EU-VAT tê bikar anîn û li ser fatûreyan tê çap kirin.<br> <strong>Em bi tundî pêşniyar dikin ku hejmara VAT ya Dikana xwe lê zêde bikin,</strong> ji ber ku wekî din encamên şêwirmendiya VIES dibe ku ji bo mebestên hesabdariyê derbasdar nebin.<br> Yanî: <code>ATU99999999</code> an <code>EE999999999</code> .','Reverse charge' => 'Barkirina berevajî','Apply reverse charge mechanism' => 'Mekanîzma barkirina berevajî bicîh bîne','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Rêjeya bacê li ser sifirê deyne û dema ku jimareya VAT ya xerîdar derbasdar be, &quot;Berdê berevajî&quot; li ser fatûreyan nîşan bide. Li gorî welatê firotgehê, dibe ku nivîsek &quot;Berdê berevajî&quot; ya cuda hewce be.','Same country' => 'Heman welat','Apply reverse charge mechanism for transactions in the shop country:' => 'Mekanîzmaya barkirina berevajî ji bo danûstandinên li welatê firotgehê bicîh bîne:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Dihêle ku mekanîzmaya barkirina berevajî ji bo danûstandinên di navbera pargîdaniyên li heman welatê firotgehê de were sepandin.','Reverse charge exceptions' => 'Îstîsnayên barkirina berevajî','Select additional countries to skip applying the reverse charge mechanism.' => 'Ji bo ku hûn sepandina mekanîzmaya barkirina berevajî ji bîr bikin, welatên din hilbijêrin.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Bac dê ji siparîşên ji van welatan were stendin, her çend hejmareke VAT-ê ya derbasdar jî were dayîn.','Reverse charge label on invoices' => 'Etîketa barkirina berevajî li ser fatûreyan','Set the label of "reverse charge" on the checkout page and order details.' => 'Etîketa &quot;barkirina berevajî&quot; li ser rûpela dravdanê û hûrguliyên siparîşê bicîh bikin.','Reverse charge text on invoices' => 'Nivîsa barkirina berevajî li ser fatûreyan','Set the label of "reverse charge" text on invoices.' => 'Etîketa nivîsa &quot;barkirina berevajî&quot; li ser fatûreyan bicîh bike.','Tax to be paid on reverse charge basis' => 'Baca ku li ser bingeha barkirina berevajî were dayîn','Company name' => 'Navê şîrketê','Autocomplete company name from VAT number' => 'Navê şîrketê ji jimareya VATê bixweber temam bike','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Navê şîrketa fatûreyê li gorî hejmara VAT-ê ya derbasdar a ku ji hêla xerîdar ve hatî peyda kirin dagirin.','Company name editing' => 'Guherandina navê şîrketê','Allow editing of auto-filled company name' => 'Destûrê bide guherandina navê şîrketê yê bixweber dagirtî','When enabled, customers can change the company name associated with the provided VAT number.' => 'Dema ku çalak be, xerîdar dikarin navê pargîdaniya ku bi hejmara VAT-ê ya peyda kirî ve girêdayî ye biguherînin.','EU-VAT for digital goods' => 'VAT-ya YE ji bo kelûpelên dîjîtal','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'Ji 1ê Çileya 2015an pê ve, guhertin di rêziknameyên VATê yên YEyê yên derbarê kelûpelên dîjîtal de hatine kirin, ku bi taybetî bandorê li danûstandinên B2C dikin. VATê li ser kelûpelên dîjîtal divê li gorî cihê xerîdar were hesibandin, û delîlên vê yekê divê werin berhevkirin (navnîşana IP û navnîşana fatûreyê).','Tax classes for digital goods' => 'Çînên bacê ji bo kelûpelên dîjîtal','Select some tax classes' => 'Hin çînên bacê hilbijêrin','Location evidence' => 'Delîlên cihê','Collect customer\'s location evidence' => 'Delîlên cîhê xerîdar berhev bikin','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Navnîşana IP-ê tomar dike û wê li gorî navnîşana fatûreyê ya xerîdar piştrast dike. Ger welatê ji navnîşana fatûreyê û IP-ya wan li hev nayên, xerîdar divê navnîşana fatûreya xwe bi nîşankirina qutiyek li ser rûpela dravdanê piştrast bike.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Ev vebijêrk di Fluid Checkout de tê birêvebirin. <a href="%s">Wê di mîhengên hesabên xerîdar de biguherîne</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Ev vebijêrk di Fluid Checkout de tê birêvebirin. Wê di bin Fluid Checkout &gt; Hesabên xerîdar de biguherînin.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Ev vebijêrk di Fluid Checkout de tê birêvebirin. Dema ku Fluid Checkout tê çalak kirin, cihê şandinê her gav wekî &quot;Navnîşana şandinê ya xerîdar wekî xwerû&quot; tê danîn. Xerîdar hîn jî dikarin di dema kirînê de navnîşanên şandin û fatûreyê yên cûda bidin.<br><br> Vebijêrkek ji bo destnîşankirina navnîşana fatûreyê ya xwerû wekî navnîşana şandinê di <a href="%s">mîhengên Fluid Checkout</a> de heye.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Ev vebijêrk di Fluid Checkout de tê birêvebirin. Dema ku Fluid Checkout tê çalak kirin, cihê şandinê her gav wekî &quot;Navnîşana şandinê ya xerîdar wekî xwerû&quot; tê danîn. Xerîdar hîn jî dikarin di dema kirînê de navnîşanên şandin û fatûreyê yên cûda bidin.<br><br> Vebijêrkek ji bo destnîşankirina navnîşana fatûreyê ya xwerû wekî navnîşana şandinê li WooCommerce &gt; Mîheng &gt; Fluid Checkout heye.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Ev mîheng ji bo WP Admin &gt; Fluid Checkout &gt; Settings hatine veguhastin.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Ev tabloya Mîhengên WooCommerce kevnar e û dê di Fluid Checkout 6.0 de were rakirin.','Go to settings page' => 'Biçe rûpela mîhengan','Hide this tab permanently' => 'Vê tabloyê bi awayekî mayînde veşêre','Site report preview' => 'Pêşdîtina rapora malperê','This is the data that would be included in the next site environment report based on your current settings.' => 'Ev ew dane ne ku dê li gorî mîhengên we yên niha di rapora jîngeha malperê ya bê de cih bigirin.','Loading report preview...' => 'Pêşdîtina raporê tê barkirin...','Could not load the site report preview. Try again.' => 'Nikare pêşdîtina rapora malperê bar bike. Dîsa biceribîne.','Could not send the site report. Try again.' => 'Nikaribû rapora malperê bişîne. Dîsa biceribîne.','Site report sent successfully.' => 'Rapora malperê bi serkeftî hate şandin.','Enable and send now' => 'Niha çalak bike û bişîne','Close' => 'Nêzîkî','A site report request is already in progress. Try again in a moment.' => 'Daxwazek ji bo rapora malperê jixwe di pêvajoyê de ye. Piştî demekê dîsa biceribînin.','Site environment reporting is disabled.' => 'Raporkirina jîngeha malperê neçalak e.','No site report data is available to send.' => 'Tu daneyên rapora malperê ji bo şandinê tune ne.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Ev domaina malperê nikare raporên jîngehê bişîne (domainên herêmî an jî yên pêşveçûnê ne tê de ne).','A site report was sent recently. Try again later.' => 'Raportek malperê vê dawiyê hat şandin. Paşê dîsa biceribînin.','The site report could not be sent. Try again later.' => 'Rapora malperê nehat şandin. Paşê dîsa biceribînin.','Site environment reporting is not available.' => 'Raporkirina jîngeha malperê ne berdest e.','No site report data is available for the selected settings.' => 'Ji bo mîhengên bijartî ti daneyên rapora malperê tune ne.','You are not allowed to manage site reports.' => 'Destûr nayê dayîn ku hûn raporên malperê birêve bibin.','PRO feature' => 'Taybetmendiya PRO','Other plugins' => 'Pêvekên din','Get only this add-on &mdash; %s' => 'Tenê vê pêvekê bistîne — %s','Install add-on' => 'Pêveka saz bike','Upgrade to PRO &mdash; %s' => 'Nûve bike bo PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => 'Ji bo vekirina van vebijarkan <a target="_blank" href="%1$s">%2$s bistînin</a> .','Add-on' => 'Zêdekirin','View documentation' => 'Belgekirinê bibîne','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Daxwaz bikarhênerekî WordPress-ê yê têketî hewce dike. Ji bo bikaranîna daneyên bikarhênerê heyî, user_id-ê ji bîr bikin, an jî dema ku bangker dikare wî bikarhênerî biguherîne, user_id-ê bidin hedefgirtina hesabê din (qabiliyeta edit_user). Daxwazên bêdestûr fc_api_forbidden vedigerînin. Nasnameyeke bikarhêner a nederbasdar fc_api_user_not_found vedigerîne.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 bi { &quot;dane&quot;: { ... } } dema ku destgir bargiraniyek vedigerîne.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 bi { &quot;serkeftin&quot;: rast } dema ku barkêş tune be (mînak DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Têkçûn çewtiya WordPress REST JSON ji WP_Error (code, message, data.status) vedigerînin. Kodên têl pêşgira fc_api_* bi kar tînin.','Forbidden access.' => 'Gihîştina qedexekirî.','Target user was not found.' => 'Bikarhênerê hedef nehat dîtin.','This feature is not available.' => 'Ev taybetmendî peyda nabe.','A required address field is missing.' => 'Qadeke navnîşanê ya pêwîst tune ye.','Postcode or ZIP is invalid.' => 'Koda postayê an jî zîp ne derbasdar e.','Phone number is invalid.' => 'Hejmara telefonê ne derbasdar e.','State or county is invalid.' => 'Dewlet an wîlayet ne derbasdar e.','Country is invalid or has no address fields.' => 'Welat ne derbasdar e an jî qadên navnîşanê tê de tune ne.','The request could not be processed.' => 'Daxwaz nehat pêvajokirin.','Back to previous step' => 'Vegere gava berê','Skip to settings' => 'Biçe ser mîhengan','Start over and return to the first guided setup step' => 'Ji nû ve dest pê bike û vegere gava sazkirinê ya rêberkirî ya yekem','Start over' => 'Ji nû ve dest pê bike','Please complete all sub-steps before continuing.' => 'Ji kerema xwe berî berdewamkirinê hemû gavên jêrîn temam bikin.','Expand' => 'Firehkirin','Collapse' => 'Jiberhevketin','Skip' => 'Hilperkîn','Mark as complete' => 'Wekî temam nîşan bike','Mark as incomplete' => 'Wekî netemam nîşan bike','View full-size image: %s' => 'Wêneyê bi mezinahiya tevahî bibîne: %s','Full-size setup guide image' => 'Wêneya rêbernameya sazkirinê ya bi mezinahiya tevahî','Close image' => 'Wêneyê bigire','Fluid Checkout Guided Setup' => 'Sazkirina Rêberkirî ya Kontrolkirina Şilavê','Welcome' => 'Bi xêr hatî','Explore your checkout' => 'Derbaskirina xwe ya kirînê bikole','All set' => 'Amade ye','You do not have permission to access this page.' => 'Destûra te tune ku tu bigihîjî vê rûpelê.','Go to step %1$d: %2$s' => 'Biçe gava %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Ev sazkirina rêberkirî alîkariya we dike ku hûn bi Fluid Checkout-ê re nas bibin. Gavên li jêr niha cîhên parastinê ne.','Continue to the next step when you are ready.' => 'Dema ku hûn amade ne, bi gava din berdewam bikin.','Open your store checkout to see Fluid Checkout in action.' => 'Ji bo dîtina Fluid Checkout di çalakiyê de, kaseya firotgeha xwe veke.','View checkout page' => 'Rûpela dravdanê bibîne','You can return to Fluid Checkout settings to continue configuring your store.' => 'Hûn dikarin vegerin mîhengên Fluid Checkout da ku hûn berdewam bikin bi mîhengkirina firotgeha xwe.','Review checkout and cart settings' => 'Mîhengên kirîn û selikê binirxînin','Explore add-ons from the dashboard' => 'Lêzêdekirinên ji dashboardê bigerin','Finish & go to settings' => 'Biqedîne û here mîhengan','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Vebijêrka xuyabûna qada telefona fatûreyê ji nirxa mîrasî nûve bike da ku li gorî rêzikên WooCommerce be.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Vebijêrka xuyabûna qada telefona şandinê ji nirxa mîrasî nûve bike da ku li gorî rêziknameyên WooCommerce be.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Mîhenga rengê paşxaneya kurteya fermanê li vebijarka rengê paşxaneya stûna duyemîn a sêwirana dabeşkirî ya nû kopî bike.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Taybetiya qadên hilbijartinê yên pêşkeftî her gav dema ku pêveka Biteship tê bikar anîn neçalak e.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Dema ku German Market tê bikar anîn, cihê danîna fermanê her tim wekî &quot;Li jêr kurteya fermanê&quot; tê danîn. Ew pêvek hewce dike ku bişkoka danîna fermanê û qutiyên kontrolê yên qanûnî li jêr kurteya fermanê werin nîşandan.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Dema ku Germanized for WooCommerce tê bikar anîn, cihê danîna fermanê her tim wekî &quot;Li jêr kurteya fermanê&quot; tê danîn. Ew pêvek hewce dike ku bişkoka danîna fermanê û qutiyên kontrolê yên qanûnî li jêr kurteya fermanê werin nîşandan.','Edit pickup locations' => 'Cihên wergirtinê biguherîne','Use local pickup label from WooCommerce settings' => 'Etîketa wergirtina herêmî ji mîhengên WooCommerce bikar bînin','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Dema ku çalak be, etîketa vebijarka wergirtinê li ser dravdanê bi sernavê ji mîhengên cîhê wergirtinê ya WooCommerce re li hev dike. Dema ku neçalak be, etîket nivîsa &quot;Wergirtina Herêmî&quot; ya wergerbar ji Fluid Checkout bikar tîne.','Button label for applying coupon codesApply' => 'Bikaranîn','Checkout step titleContact' => 'Têkelî','Checkout step titleShipping' => 'Shipping','Checkout step titleBilling' => 'Billing','Checkout step titlePayment' => 'Diravdanî','Checkout substep change link labelChange' => 'Gûherrandin','Checkout substep save link labelSave changes' => 'Guherandinên tomar bike','Substep review textNone.' => 'Netû.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Wêne nehat hilbijartin.','Settings sectionCart' => 'Ereboka destan','Settings sectionOrder pay' => 'Siparîşa dayina','Settings sectionThank you' => 'Sipas ji were','Settings section titleIntegrations' => 'Integrations','Settings section titleLicense keys' => 'keys License de','Captcha positionBefore place order section' => 'Berî beşa fermanê cîh','Captcha positionBefore place order button' => 'Berî bişkojka fermanê cîh','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Nêzîkî','Log in link label at checkout contact stepLog in' => 'Têkeve','Log in separator label at for when guest checkout is disabledOr continue below' => 'An jî li jêr berdewam bikin','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'An jî wek mêvan berdewam bike','Clear image selection on admin pages.Remove image' => 'Wêneyê jê bibe','shipping packagesShipping %d' => 'Şandin %d','shipping packagesShipping' => 'Şandin','Used as fallback for "Proceed to next step" button labelnext step' => 'gava din','Substep review checkbox valueYes' => 'Erê','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'Yûhenna','Dummy customer last name in the admin previewDoe' => 'Keçik','Dummy customer company in the admin previewExample Company' => 'Şîrketa Mînak','Dummy customer street address in the admin preview123 Main Street' => '123 Kolana Sereke','Dummy customer city in the admin previewAnytown' => 'Anytown','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Ji kerema xwe pakêtê li ber derî bihêlin.','Dummy product name in the admin previewBeanie' => 'Beanie','Dummy product name in the admin previewCap' => 'Devik','Dummy product name in the admin previewT-Shirt' => 'T-Shirt','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Me siparîşa we wergirt û dema ku were şandin em ê nûvekirinek ji we re bişînin.','Dummy download in the admin previewUser guide' => 'Rehbera bikaranînê','Google Places API versionsPlaces API (New)' => 'API-ya Cihên (Nû)','Google Places API versionsPlaces API (Legacy)' => 'API-ya Cihên (Mîrasî)','Brasil API versionsVersion 1' => 'Versiyon 1','Brasil API versionsVersion 2' => 'Versiyona 2','Delayed account creation benefits placeholder text✔ Checkout faster next time
✔ Manage your payment preferences
✔ View order status and history' => '✔ Cara din zûtir pere bidin ✔ Tercîhên xwe yên dravdanê birêve bibin ✔ Rewş û dîroka fermanê bibînin','VAT number field visibilityHidden' => 'Veşartî','VAT number field visibilityOptional' => 'Bixwe','VAT number field visibilityRequired' => 'Pêwîst','Delivery typeShipping to address' => 'Şandin bo navnîşanê','Delivery typeLocal pickup' => 'Wergirtina herêmî',] ];